const fs=require('fs');const path=require('path');const ROOT=path.resolve(__dirname,'..');
const MARK='CE_DATA_WAVE2B_20260809';
function p(rel){return path.join(ROOT,rel)}
function read(rel){return fs.readFileSync(p(rel),'utf8')}
function write(rel,s){fs.writeFileSync(p(rel),s)}
function insertBefore(rel,needle,html){let s=read(rel);if(s.includes(`${MARK}:${rel}`))return;const i=s.indexOf(needle);if(i<0)throw new Error(`Anchor not found ${rel}: ${needle}`);s=s.slice(0,i)+`<!-- ${MARK}:${rel} -->\n${html}\n`+s.slice(i);write(rel,s)}

insertBefore('dossiers/finances-enveloppes-fiscalite.html','<h2>1.',`<div class="case-study" id="reperes-fiscaux-2026"><h2>Repères fiscaux chiffrés — août 2026</h2><p><strong>Règles nationales vérifiées en août 2026.</strong> Les enveloppes ne modifient pas le rendement de l’actif, mais elles peuvent modifier fortement ce qui reste après impôt et les conditions de disponibilité.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Enveloppe</th><th>Repère 2026</th><th>Exemple simple</th><th>À ne pas oublier</th></tr></thead><tbody><tr><td>PEA</td><td>Versements plafonnés à 150 000 € ; PEA + PEA-PME : 225 000 € au total. Après 5 ans, gains exonérés d'IR mais prélèvements sociaux dus.</td><td>Sur 40 000 € de gain retiré après 5 ans, l'impôt sur le revenu est nul ; les prélèvements sociaux restent dus selon le taux applicable.</td><td>Avant 5 ans, le PFU applicable aux gains est de <strong>31,4 % en 2026</strong> sauf option/barème et cas d'exonération.</td></tr><tr><td>Assurance-vie &gt; 8 ans</td><td>Abattement annuel sur les gains : <strong>4 600 €</strong> seul / <strong>9 200 €</strong> couple imposé en commun.</td><td>8 000 € de gains retirés par une personne seule : après abattement, 3 400 € restent soumis à l'IR. Les prélèvements sociaux s'appliquent séparément.</td><td>Pour l'assurance-vie classique avec valeur de rachat, les prélèvements sociaux restent à <strong>17,2 %</strong> en 2026.</td></tr><tr><td>CTO</td><td>PFU de droit commun : <strong>31,4 %</strong> en 2026, soit 12,8 % d'IR + 18,6 % de prélèvements sociaux.</td><td>1 000 € de revenu mobilier soumis au PFU → 314 € de prélèvements au total, avant éventuelle option pour le barème.</td><td>L'option pour le barème est globale pour les revenus concernés : elle doit être simulée au niveau du foyer.</td></tr><tr><td>PER</td><td>Après 70 ans, les nouveaux versements ne sont plus déductibles. À la sortie en capital, les produits sont soumis en 2026 au taux global de <strong>31,4 %</strong> dans le cas prévu par la réglementation.</td><td>Versement de 10 000 € intégralement déductible dans une tranche marginale à 30 % : économie d'IR immédiate d'environ <strong>3 000 €</strong>, avant effet de la fiscalité future.</td><td>La déduction n'est pas un gain gratuit : le capital déduit à l'entrée est fiscalisé à la sortie selon le mode choisi.</td></tr></tbody></table></div><p><strong>Lecture :</strong> le PEA devient très efficace fiscalement après cinq ans pour une poche actions éligible ; l'assurance-vie apporte un abattement annuel après huit ans ; le CTO achète de la liberté d'investissement au prix d'une fiscalité de droit commun ; le PER échange une économie fiscale immédiate contre davantage de contraintes et une fiscalité future.</p><p class="source-note">Sources : <a href="https://www.impots.gouv.fr/particulier/questions/jai-un-plan-depargne-en-actions-pea-les-retraits-sont-ils-imposables" rel="noopener noreferrer">impots.gouv.fr — PEA, mise à jour 17 juillet 2026</a> ; <a href="https://www.impots.gouv.fr/particulier/lassurance-vie-et-le-pea-0" rel="noopener noreferrer">impots.gouv.fr — assurance-vie et prélèvements sociaux 2026</a> ; <a href="https://www.impots.gouv.fr/particulier/questions/jai-des-valeurs-mobilieres-comment-sont-elles-imposees" rel="noopener noreferrer">impots.gouv.fr — valeurs mobilières</a> ; <a href="https://www.economie.gouv.fr/particuliers/gerer-mon-argent/gerer-mon-budget-et-mon-epargne/comment-fonctionne-le-plan-depargne-retraite-individuel" rel="noopener noreferrer">Économie.gouv.fr — PER individuel, règles 2026</a>.</p></div>`);

insertBefore('dossiers/finances-retraite-decumulation.html','<h2>1.',`<div class="case-study" id="longevite-inflation"><h2>Deux chiffres qui changent complètement un plan de retraite</h2><p><strong>Espérance de vie observée en France en 2025 :</strong> à 65 ans, il reste en moyenne <strong>20,0 années</strong> à vivre pour un homme et <strong>23,6 années</strong> pour une femme, dans les conditions de mortalité de 2025. Une moyenne n'est pas une date de décès : une partie importante des personnes vivra plus longtemps.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Hypothèse illustrative</th><th>Dépense annuelle équivalente à 30 000 € aujourd'hui</th></tr></thead><tbody><tr><td>Aujourd'hui</td><td>30 000 €</td></tr><tr><td>Dans 10 ans avec 2 % d'inflation/an</td><td><strong>≈ 36 570 €</strong></td></tr><tr><td>Dans 20 ans</td><td><strong>≈ 44 578 €</strong></td></tr><tr><td>Dans 30 ans</td><td><strong>≈ 54 341 €</strong></td></tr></tbody></table></div><p>Le taux de 2 % du tableau est une <strong>hypothèse de simulation</strong>, pas une prévision. À titre de contexte, l'IPC français progressait de <strong>1,8 % sur un an en juin 2026</strong>. Sur trente ans, la question n'est pas de prévoir l'inflation exacte, mais de vérifier que le plan survit à plusieurs rythmes possibles.</p><p><strong>Conséquence :</strong> partir à 65 ans avec un plan qui fonctionne seulement jusqu'à 85 ans est fragile. Un stress test à 95 ans, voire au-delà, permet de voir si le capital, les pensions et la flexibilité des dépenses sont réellement suffisants.</p><p class="source-note">Sources : <a href="https://www.insee.fr/fr/statistiques/2416631" rel="noopener noreferrer">Insee — espérance de vie à divers âges, données 2025</a> ; <a href="https://www.insee.fr/fr/statistiques/9021808" rel="noopener noreferrer">Insee — IPC juin 2026</a>. Calculs d'inflation : hypothèse illustrative de 2 % par an.</p></div>`);

insertBefore('dossiers/finances-transmission-patrimoine.html','<h2>1.',`<div class="case-study" id="reperes-transmission-2026"><h2>Transmission : les ordres de grandeur fiscaux à connaître en 2026</h2><p><strong>Ces montants sont des repères nationaux, pas un montage personnalisé.</strong> Ils permettent surtout de comprendre pourquoi la date, l'âge au versement et le lien de parenté changent fortement le résultat.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Situation</th><th>Repère fiscal</th><th>Exemple</th></tr></thead><tbody><tr><td>Donation parent → enfant</td><td>Abattement de <strong>100 000 €</strong> par parent et par enfant, renouvelable après 15 ans.</td><td>Deux parents peuvent chacun utiliser leur propre abattement vis-à-vis d'un même enfant, si les conditions sont réunies.</td></tr><tr><td>Don familial de somme d'argent</td><td>Exonération pouvant atteindre <strong>31 865 €</strong> sous conditions, cumulable avec l'abattement lié à la parenté.</td><td>Un parent de moins de 80 ans peut, sous conditions, porter le total exonéré jusqu'à <strong>131 865 €</strong> pour un enfant majeur.</td></tr><tr><td>Exonération temporaire 2025–2026</td><td>Jusqu'à <strong>100 000 €</strong> par donateur/donataire et <strong>300 000 €</strong> par bénéficiaire pour certains projets immobiliers ou de rénovation, jusqu'au 31 décembre 2026.</td><td>Le don doit être utilisé dans le délai et pour les usages prévus par le dispositif.</td></tr><tr><td>Assurance-vie · primes versées avant 70 ans</td><td>Abattement de <strong>152 500 € par bénéficiaire</strong>, puis prélèvement de 20 % jusqu'à 700 000 € de part taxable et 31,25 % au-delà.</td><td>Le seuil est apprécié par bénéficiaire pour l'ensemble des contrats concernés.</td></tr><tr><td>Assurance-vie · primes versées après 70 ans</td><td>Les primes au-delà d'un abattement global de <strong>30 500 €</strong> sont soumises aux droits de succession selon le lien de parenté.</td><td>L'abattement de 30 500 € est global pour l'ensemble des contrats d'un même assuré.</td></tr></tbody></table></div><p><strong>Le vrai enseignement :</strong> transmettre 100 000 € par donation, 100 000 € par assurance-vie ou laisser 100 000 € dans la succession ne produit pas nécessairement le même résultat. Mais l'optimisation fiscale ne doit jamais faire donner un capital dont le donateur pourrait avoir besoin pour sa propre retraite.</p><p class="source-note">Sources : <a href="https://www.service-public.fr/particuliers/vosdroits/F36656" rel="noopener noreferrer">Service-Public — droits de donation et dons de sommes d'argent</a> ; <a href="https://www.impots.gouv.fr/particulier/questions/je-suis-beneficiaire-dune-assurance-vie-comment-la-declarer" rel="noopener noreferrer">impots.gouv.fr — assurance-vie et décès</a>. Règles à revérifier avant toute opération.</p></div>`);

insertBefore('dossiers/formation-vaut-elle-le-cout.html','<h2>1.',`<div class="case-study" id="cpf-2026"><h2>CPF 2026 : « financé » ne veut plus forcément dire zéro euro à payer</h2><p>Depuis le <strong>1er avril 2026</strong>, la participation financière obligatoire pour mobiliser le CPF est fixée à <strong>150 €</strong>, sauf cas d'exonération. Les demandeurs d'emploi font partie des publics exonérés.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Exemple</th><th>Prix</th><th>Droits CPF disponibles</th><th>Paiement du titulaire</th></tr></thead><tbody><tr><td>Droits suffisants</td><td>1 000 €</td><td>1 000 €</td><td><strong>150 €</strong> ; 850 € de CPF mobilisés</td></tr><tr><td>Droits insuffisants</td><td>3 000 €</td><td>1 500 €</td><td>Au moins le reste à financer selon les abondements et règles applicables</td></tr></tbody></table></div><p>La loi de finances 2026 a également introduit des plafonds de mobilisation pour certaines catégories : par exemple <strong>1 600 € pour un bilan de compétences</strong> et <strong>1 500 € pour une certification du Répertoire spécifique</strong> (hors exception CléA), selon les règles publiées par Mon Compte Formation.</p><p><strong>Mais le principal coût reste souvent ailleurs :</strong> une formation à 6 000 € intégralement financée peut coûter davantage si elle entraîne quatre mois sans salaire, des déplacements ou retarde un retour à l'emploi. Le financement ne remplace donc jamais le calcul du coût économique total.</p><p class="source-note">Source : <a href="https://www.moncompteformation.gouv.fr/espace-public/une-participation-financiere-pourquoi-et-comment" rel="noopener noreferrer">Mon Compte Formation — participation financière obligatoire 2026</a> ; <a href="https://financeurs.moncompteformation.gouv.fr/espace-public/evolution-des-regles-de-financement-le-cpf-la-suite-de-la-loi-de-finances-2026" rel="noopener noreferrer">Mon Compte Formation — évolutions de financement 2026</a>.</p></div>`);

insertBefore('dossiers/negocier-salaire-responsabilites.html','<h2>1.',`<div class="case-study" id="reperes-salaires"><h2>Un salaire « moyen » ne suffit pas : regardez la distribution</h2><p><strong>Données Insee, secteur privé, année 2024 publiées dans l'édition 2026.</strong> Le salaire net mensuel moyen en équivalent temps plein est d'environ <strong>2 730 €</strong>, mais le salaire médian est de <strong>2 190 €</strong>. Un salarié sur dix gagne moins de <strong>1 492 €</strong> et un sur dix plus de <strong>4 334 €</strong>.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Repère</th><th>Net mensuel EQTP</th><th>Pourquoi c'est utile</th></tr></thead><tbody><tr><td>1er décile</td><td>&lt; 1 492 €</td><td>Donne un repère du bas de la distribution.</td></tr><tr><td>Médiane</td><td><strong>2 190 €</strong></td><td>La moitié gagne moins, l'autre moitié davantage.</td></tr><tr><td>Moyenne</td><td>≈ 2 730 €</td><td>Tirée vers le haut par les rémunérations élevées.</td></tr><tr><td>9e décile</td><td>&gt; 4 334 €</td><td>Repère du haut de la distribution.</td></tr></tbody></table></div><p>La taille de l'employeur compte aussi : en 2024, l'Insee observe en moyenne <strong>2 190 € nets</strong> dans les unités de moins de 10 salariés contre <strong>3 260 €</strong> dans les sociétés de 5 000 salariés ou plus. Ces chiffres ne donnent pas « votre salaire ». Ils montrent pourquoi une négociation doit comparer métier, région, taille d'entreprise, expérience et responsabilités plutôt qu'une moyenne nationale isolée.</p><p class="source-note">Sources : <a href="https://www.insee.fr/fr/statistiques/8733089?sommaire=8733125" rel="noopener noreferrer">Insee — salaires dans le privé, édition 2026</a> ; <a href="https://www.insee.fr/fr/statistiques/8733091?sommaire=8733125" rel="noopener noreferrer">Insee — caractéristiques des employeurs</a>.</p></div>`);

